const configuracao = { installation_ids: [Number($env.APROVA_CHAT_INSTALLATION_ID || 0)] };
const ids = [...new Set(configuracao.installation_ids)];
if (!ids.length || ids.length > 50 || ids.some(id => !Number.isSafeInteger(id) || id <= 0)) {
  throw new Error('Configure APROVA_CHAT_INSTALLATION_ID no ambiente do n8n com um ID real de instalação do GitHub App.');
}
const agora = new Date();
const hoje = new Date(Date.UTC(agora.getUTCFullYear(), agora.getUTCMonth(), agora.getUTCDate()));
const fim = new Date(hoje);
fim.setUTCDate(fim.getUTCDate() - (fim.getUTCDay() + 6) % 7);
const inicio = new Date(fim);
inicio.setUTCDate(inicio.getUTCDate() - 7);
return ids.map(installation_id => ({ json: {
  installation_id, inicio: inicio.toISOString().slice(0, 10), fim: fim.toISOString().slice(0, 10),
} }));

const crypto = require('crypto');
const { installation_id, inicio, fim } = $json;
if (!Number.isSafeInteger(installation_id) || installation_id <= 0 ||
    typeof inicio !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(inicio)) throw new Error('Consulta inválida.');
const segredo = $env.N8N_SEGREDO_ACOES;
if (!segredo) throw new Error('N8N_SEGREDO_ACOES ausente no n8n.');
if (!$env.SLACK_INCOMING_WEBHOOK_URL) throw new Error('SLACK_INCOMING_WEBHOOK_URL ausente no n8n.');
const query = 'installation_id=' + installation_id + '&inicio=' + inicio;
const timestamp = Math.floor(Date.now() / 1000).toString();
return { json: { installation_id, inicio, fim, requisicao: {
  url: ($env.APROVA_API_URL || 'http://host.docker.internal:8080').replace(/\/+$/, '') + '/reports/weekly?' + query,
  headers: {
    'X-Aprova-Timestamp': timestamp,
    'X-Aprova-Assinatura': 'sha256=' + crypto.createHmac('sha256', segredo).update(timestamp + '.' + query).digest('hex'),
  },
} } };

const esperado = $('03 | Assinar Consulta à API').item.json;
const r = $json.body;
const contagens = ['total_execucoes', 'concluidas', 'rejeitadas', 'falhas', 'em_andamento',
  'exigiram_aprovacao_humana', 'revertidas'];
const finalizadas = r ? r.concluidas + r.rejeitadas + r.falhas : NaN;
if ($json.statusCode !== 200 || !r || Array.isArray(r) ||
    r.installation_id !== esperado.installation_id ||
    r.inicio !== esperado.inicio + 'T00:00:00Z' || r.fim !== esperado.fim + 'T00:00:00Z' ||
    contagens.some(k => !Number.isSafeInteger(r[k]) || r[k] < 0) ||
    finalizadas + r.em_andamento !== r.total_execucoes ||
    r.exigiram_aprovacao_humana > r.total_execucoes ||
    (finalizadas === 0 ? r.taxa_sucesso !== null :
      typeof r.taxa_sucesso !== 'number' || !Number.isFinite(r.taxa_sucesso) ||
      Math.abs(r.taxa_sucesso - r.concluidas / finalizadas) > 0.000001)) {
  throw new Error('Relatório semanal inválido ou de instalação/período diferente. Digest não enviado.');
}
const data = iso => iso.slice(8, 10) + '/' + iso.slice(5, 7) + '/' + iso.slice(0, 4);
const ultimoDia = new Date(r.fim);
ultimoDia.setUTCDate(ultimoDia.getUTCDate() - 1);
const taxa = r.taxa_sucesso === null ? 'Não disponível — nenhuma execução finalizada.' :
  (r.taxa_sucesso * 100).toFixed(1).replace('.', ',') + '%';
const texto = [
  'aPRova | Digest semanal',
  'Instalação: ' + r.installation_id,
  'Período: ' + data(r.inicio) + ' a ' + data(ultimoDia.toISOString()) + ' (UTC)',
  '',
  'Total de execuções: ' + r.total_execucoes,
  'Taxa de sucesso: ' + taxa,
  'Exigiram aprovação humana: ' + r.exigiram_aprovacao_humana,
  'Revertidas: ' + r.revertidas,
  '',
  'Taxa de sucesso = concluídas / (concluídas + rejeitadas + falhas).',
  'Execuções em andamento: ' + r.em_andamento + '.',
  'Reversões contabilizadas pelo núcleo na semana; podem se referir a análises anteriores.',
].join('\n');
return { json: {
  installation_id: r.installation_id, inicio: r.inicio, fim: r.fim, metricas: r,
  slack_payload: { text: texto, blocks: [{ type: 'section', text: { type: 'plain_text', text: texto } }],
    mrkdwn: false, unfurl_links: false, unfurl_media: false },
} };

const resposta = $json.body ?? $json.data;
if ($json.statusCode !== 200 || typeof resposta !== 'string' || resposta.trim() !== 'ok') {
  throw new Error('Slack não confirmou o recebimento. Confira a execução antes de reenviar para evitar duplicação.');
}
const digest = $('05 | Validar e Formatar Digest').item.json;
return { json: { status: 'enviado', installation_id: digest.installation_id,
  inicio: digest.inicio, fim: digest.fim } };
